def solve_n3():
    N = 3
    # Coloring scheme: C(i, j, k) = i + j + k
    colors = {}
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            for k in range(1, N + 1):
                color = i + j + k
                colors[(i, j, k)] = color

    all_colors = set(colors.values())
    max_colors = len(all_colors)

    # Helper function to get the set of colors for a specific slice
    def get_slice_set(fixed_coord, axis, N, colors):
        s = set()
        if axis == 'X':
            # Slice fixed at i=fixed_coord. Colors determined by j and k.
            for j in range(1, N + 1):
                for k in range(1, N + 1):
                    s.add(colors[(fixed_coord, j, k)])
        elif axis == 'Y':
            # Slice fixed at j=fixed_coord. Colors determined by i and k.
            for i in range(1, N + 1):
                for k in range(1, N + 1):
                    s.add(colors[(i, fixed_coord, k)])
        elif axis == 'Z':
            # Slice fixed at k=fixed_coord. Colors determined by i and j.
            for i in range(1, N + 1):
                for j in range(1, N + 1):
                    s.add(colors[(i, j, fixed_coord)])
        return s

    # Generate all sets for each axis. Convert sets to sorted tuples to make them hashable.
    S_X_tuples = {tuple(sorted(list(get_slice_set(i, 'X', N, colors)))) for i in range(1, N + 1)}
    S_Y_tuples = {tuple(sorted(list(get_slice_set(j, 'Y', N, colors)))) for j in range(1, N + 1)}
    S_Z_tuples = {tuple(sorted(list(get_slice_set(k, 'Z', N, colors)))) for k in range(1, N + 1)}

    # Check if the collections of sets are equal
    constraint_satisfied = (S_X_tuples == S_Y_tuples) and (S_X_tuples == S_Z_tuples)

    print(f"N={N}")
    print(f"Total distinct colors used: {max_colors}")
    print(f"Constraint satisfied: {constraint_satisfied}")

solve_n3()

